custom_css:
/* MoodTube × MoonThemes Moon Bubble Green — зелёный гаджет: ЖК-экраны, металл, светодиоды, как в теме таверны */
:root, [data-mt-theme="custom"] {
    --b-orb-pink: radial-gradient(circle at 50% 70%, #f2a6ef 0%, #c45fc9 70%);
    --b-orb-violet: radial-gradient(circle at 50% 70%, #c7b8ff 0%, #8a73ee 70%);
    --b-orb-blue: radial-gradient(circle at 50% 70%, #a9c8ff 0%, #5a83ec 70%);
    --b-orb-deep: radial-gradient(circle at 50% 70%, #8d7cf2 0%, #5a46c9 75%);
    --b-font: 'Comfortaa', 'Noto Sans', sans-serif;
    --b-window: #e3e7d6; --b-card: #f1f3e8; --b-card2: #e8ecdb; --b-field: #f7f8f0;
    --b-line: #7e8a74; --b-soft: #bcc5ae; --b-accent: #3d6b2f; --b-accent2: #9fb08f; --b-pink: #ff3d97;
    --b-ink: #1e291b; --b-text: #2a3526; --b-muted: #5c6856; --b-dim: #8a9483;
    --b-pill: linear-gradient(180deg, #2e4a27 0%, #1d3219 100%);
    --b-pill-off: linear-gradient(180deg, #f4f6ee 0%, #d5dbc9 55%, #b9c1ad 100%);
    --b-pill-off-ink: #2a3526;
    --b-gloss: radial-gradient(ellipse 55% 30% at 50% 20%, rgba(255, 255, 255, 0.45), rgba(255, 255, 255, 0) 100%);
    --b-glow: 0 0 0 1px rgba(255, 255, 255, 0.5) inset;
    --b-shadow: 0 2px 0 rgba(0, 0, 0, 0.25), 0 8px 18px rgba(0, 0, 0, 0.35);
    --b-orb-pink: radial-gradient(circle at 50% 45%, #ff9ccb 0%, #ff3d97 55%, #b3125e 100%);
    --b-orb-violet: radial-gradient(circle at 50% 35%, #8d9886 0%, #4f5a49 60%, #2f382c 100%);
    --b-orb-blue: radial-gradient(circle at 50% 45%, #e6ff9c 0%, #8fd14a 55%, #4f8a1f 100%);
    --b-orb-deep: radial-gradient(circle at 50% 35%, #7c8775 0%, #434d3e 60%, #262d23 100%);
    --b-font: 'IBM Plex Mono', 'Noto Sans Mono', monospace;

    --mt-slider-track: var(--b-soft);
    --mt-slider-track-height: 6px;
    --mt-slider-track-radius: 999px;
    --mt-slider-thumb-size: 16px;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-bg: #ffffff;
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: 2px solid var(--b-accent);
    --mt-slider-thumb-shadow: 0 2px 6px rgba(70, 50, 170, 0.35);
    --mt-slider-progress: linear-gradient(90deg, var(--b-accent), var(--b-pink));

    --mt-overlay: rgba(40, 25, 110, 0.35);
    --mt-modal-shadow: var(--b-shadow);
    --mt-dock-cover-radius: 10px;
    /* Раскрытый плеер в полосе: шапка-пилюля сверху съедает место, чуть выше стандартного */
    --mt-dock-panel-height: min(380px, 56vh);
    --mt-pl-spotify-tab: var(--b-accent);
    --mt-pl-spotify-tab-text: #fff;
}

/* ===== Окно плеера ===== */
.mt-player, .mt-player *, .mt-fab, .mt-dock, .mt-dock *, #mt-settings-modal *, .mt-pl-modal * { font-family: var(--b-font); }
.mt-player {
    background: var(--b-window);
    border: 2px solid var(--b-line);
    border-radius: 24px;
    box-shadow: var(--b-shadow);
    backdrop-filter: none; -webkit-backdrop-filter: none;
    padding: 50px 14px 14px;
    color: var(--b-text);
}
/* Заголовок — пилюля с градиентом, справа шарики-кнопки */
.mt-player-header {
    top: 8px; left: 8px; right: 8px; height: 32px;
    padding: 0 112px 0 14px; box-sizing: border-box;
    align-items: center; gap: 6px;
    border: 2px solid var(--b-line); border-radius: 999px;
    background: var(--b-pill); box-shadow: var(--b-glow);
    color: #fff; font-size: 12px; font-weight: 700;
}
.mt-player-header-title { color: #fff; }
.mt-player-header-title::before { content: '♪ '; }
.mt-player-status { color: #fff; opacity: 0.85; font-weight: 400; }
.mt-player-status::before { content: '· '; }
.mt-player .mt-window-btn {
    top: 13px; width: 22px; height: 22px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    border: 1.5px solid rgba(255, 255, 255, 0.85); border-radius: 50%;
    background: var(--b-gloss), var(--b-orb-violet);
    color: #fff; font-size: 10px;
}
.mt-player .mt-btn-close { right: 14px; background: var(--b-gloss), var(--b-orb-pink); }
.mt-player .mt-btn-settings { right: 40px; }
.mt-player .mt-btn-search { right: 66px; background: var(--b-gloss), var(--b-orb-blue); }
.mt-player .mt-btn-lyrics { right: 92px; }
.mt-player .mt-window-btn:hover, .mt-player .mt-btn-search.mt-is-open, .mt-player .mt-btn-lyrics.mt-is-open { color: #fff !important; transform: scale(1.08); }

/* Обложка — круг в сиреневой рамке */
.mt-cover { border: 3px solid var(--b-accent2); background: var(--b-card2); box-shadow: var(--b-shadow); }
.mt-cover-hole { width: 16px; height: 16px; border: 1.5px solid #fff; background: var(--b-gloss), var(--b-orb-pink); }

.mt-track-title { color: var(--b-ink); font-size: 14px; font-weight: 700; }
.mt-track-subtitle { color: var(--b-muted); font-size: 11px; font-weight: 700; }
.mt-time { color: var(--b-muted); font-size: 10px; }

/* Кнопки — блестящие шарики, «играть» — большой розовый */
.mt-player .mt-btn:hover, .mt-dock .mt-dock-btn:hover { transform: none; }
.mt-controls { gap: 8px; }
.mt-controls .mt-btn {
    width: 34px; height: 34px; box-sizing: border-box; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center;
    border: 2px solid var(--b-accent2);
    background: var(--b-gloss), var(--b-orb-deep);
    box-shadow: var(--b-glow);
    color: #fff; font-size: 13px;
}
.mt-controls .mt-btn:hover { color: #fff; filter: brightness(1.08); }
.mt-controls .mt-btn:active { transform: scale(0.9); }
.mt-controls .mt-btn-play { width: 46px; height: 46px; background: var(--b-gloss), var(--b-orb-pink); font-size: 17px; }
.mt-controls .mt-btn-accent { color: #fff; }
.mt-btn-ai.mt-is-busy { background: var(--b-gloss), var(--b-orb-blue) !important; }
.mt-btn-favorite { color: var(--b-accent); }
.mt-btn-favorite.mt-is-active { color: var(--b-pink); }
.mt-volume-icon { color: var(--b-accent); }

/* Текст песни */
.mt-lyric-line { color: var(--b-text); }
.mt-lyric-line.mt-is-active { color: var(--b-accent); }
.mt-lyrics-message i { color: var(--b-accent); }

/* ===== Очередь, плейлисты, поиск ===== */
.mt-panel { inset: 46px 8px 8px 8px; padding: 8px; background: var(--b-window); border-radius: 0 0 18px 18px; }
.mt-panel-header-left { margin-right: 0; }
.mt-panel-title { color: var(--b-accent); font-size: 13px; }
.mt-panel .mt-btn { color: var(--b-accent); }
.mt-queue-item { background: var(--b-card); border: 2px solid var(--b-soft); border-radius: 14px; margin-bottom: 6px; }
.mt-queue-item:hover { background: var(--b-card2); }
.mt-queue-item.mt-is-current { background: var(--b-pill); border-color: var(--b-line); }
.mt-queue-item.mt-is-current .mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-now, .mt-queue-item.mt-is-current .mt-pl-count, .mt-queue-item.mt-is-current .mt-queue-add { color: #fff; }
.mt-queue-title { color: var(--b-text); }
.mt-queue-now, .mt-queue-add, .mt-pl-section-add { color: var(--b-accent); }
.mt-queue-thumb, .mt-pl-cover { border-radius: 10px; }
.mt-queue-empty, .mt-pl-section-title { color: var(--b-muted); }
.mt-pl-cover-fav { background: var(--b-gloss), var(--b-orb-pink); color: #fff; }
.mt-pl-tabs { gap: 6px; }
.mt-pl-tab, .mt-pl-tool, .mt-pl-inline-ok, .mt-pl-inline-cancel { border: 2px solid var(--b-line); border-radius: 999px; background: var(--b-pill-off); box-shadow: var(--b-glow); color: var(--b-pill-off-ink); font-weight: 700; }
.mt-pl-tab.mt-is-active, .mt-pl-tab[data-mt-tab="spotify"].mt-is-active, .mt-pl-tool.mt-pl-play, .mt-pl-inline-ok { background: var(--b-pill); color: #fff; }
.mt-panel-search { background: var(--b-window) !important; }
#moodtube-search-container #moodtube-search-input { border-radius: 999px !important; border: 2px solid var(--b-soft) !important; background: var(--b-field) !important; color: var(--b-text) !important; }
#moodtube-search-container #moodtube-search-go { border-radius: 50% !important; border: 2px solid var(--b-accent2) !important; background: var(--b-gloss), var(--b-orb-pink) !important; color: #fff !important; }

/* Окно «Добавить в плейлист» */
.mt-pl-modal-box { border: 2px solid var(--b-line); border-radius: 22px; background: var(--b-window); box-shadow: var(--b-shadow); padding: 6px; }
.mt-pl-modal-header { border: 2px solid var(--b-line); border-radius: 999px; background: var(--b-pill); color: #fff; padding: 4px 6px 4px 12px; }
.mt-pl-modal-title { color: #fff; }
.mt-pl-modal-close { width: 22px; height: 22px; border-radius: 50%; display: flex; align-items: center; justify-content: center; border: 1.5px solid #fff; background: var(--b-gloss), var(--b-orb-pink); color: #fff; font-size: 10px; }
.mt-pl-modal-track { color: var(--b-muted); }
.mt-pl-option { border-radius: 12px; }
.mt-pl-option:hover { background: var(--b-card2); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--b-pink); }

/* ===== Плавающая кнопка — шарик ===== */
.mt-fab { border: 2px solid var(--b-accent2); border-radius: 50%; background: var(--b-gloss), var(--b-orb-deep); box-shadow: var(--b-glow), var(--b-shadow); color: #fff; }
.mt-fab.mt-is-playing { background: var(--b-gloss), var(--b-orb-pink); }
#moodtube-fab.mt-playing::before { border-top-color: var(--b-pink); }

/* ===== Полоса под шапкой — тоже пузырь: скруглённое окно в рамке ===== */
.mt-dock { margin: 0; border: 2px solid var(--b-line); border-radius: 22px; background: var(--b-window); box-shadow: var(--b-shadow); backdrop-filter: none; -webkit-backdrop-filter: none; color: var(--b-text); }
.mt-dock-bar { background: var(--b-pill-off); }
.mt-dock-inner { gap: 10px; padding: 6px 10px 12px; }
.mt-dock-cover { border: 2px solid var(--b-accent2); }
/* Раскрытый плеер под полосой: продолжение того же окна */
.mt-player.mt-player-docked { border: none; border-top: 2px solid var(--b-soft); border-radius: 0 0 20px 20px; background: var(--b-window); box-shadow: none; padding: 50px 14px 14px; }
.mt-player.mt-player-docked .mt-panel { border-radius: 0 0 18px 18px; }
.mt-dock-title { color: var(--b-ink); font-size: 12px; font-weight: 700; }
.mt-dock-subtitle { color: var(--b-muted); font-size: 11px; }
.mt-dock-btn { width: 28px; height: 28px; box-sizing: border-box; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; border: 1.5px solid var(--b-accent2); background: var(--b-gloss), var(--b-orb-deep); color: #fff; font-size: 11px; }
.mt-dock-play { background: var(--b-gloss), var(--b-orb-pink); }
.mt-dock-btn:hover { color: #fff; }
.mt-dock-fav.mt-is-active { background: var(--b-gloss), var(--b-orb-pink); }
.mt-dock-progress { left: 16px; right: 16px; bottom: 4px; height: 4px; background: var(--b-soft); border-radius: 999px; }
/* Телефон: восемь шариков должны влезть рядом с названием */
@media (max-width: 600px) {
    .mt-dock-inner { gap: 6px; padding: 6px 8px 12px; }
    .mt-dock-controls { gap: 4px; }
    .mt-dock-btn { width: 26px; height: 26px; font-size: 10px; }
    .mt-dock-fav { display: none; }
}
.mt-dock-progress-fill { background: linear-gradient(90deg, var(--b-accent), var(--b-pink)); border-radius: 999px; }

/* ===== Окно настроек ===== */
#mt-settings-modal .mt-flex-container { background: var(--b-window); border: 2px solid var(--b-line); border-radius: 24px; padding: 6px; color: var(--b-text); }
#mt-settings-modal .mt-header { border: 2px solid var(--b-line); border-radius: 999px; background: var(--b-pill); box-shadow: var(--b-glow); padding: 4px 6px 4px 14px; }
#mt-settings-modal .mt-header h3 { color: #fff; font-size: 14px; font-weight: 700; letter-spacing: 0; }
#mt-settings-modal .mt-header-icon { color: #fff; }
#mt-settings-modal .mt-close { width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; border: 1.5px solid #fff; background: var(--b-gloss), var(--b-orb-pink); color: #fff; font-size: 11px; }
#mt-settings-modal .mt-category { background: var(--b-card); border: 2px solid var(--b-soft); border-radius: 18px; }
#mt-settings-modal .mt-cat-title:hover { background: transparent; }
#mt-settings-modal .mt-cat-title h4 { color: var(--b-accent); font-size: 12px; font-weight: 700; letter-spacing: 0.04em; }
#mt-settings-modal .mt-cat-title i:first-child, #mt-settings-modal .mt-chevron { color: var(--b-accent); }
#mt-settings-modal .mt-label { color: var(--b-muted); }
#mt-settings-modal .mt-label-accent { color: var(--b-ink); font-weight: 700; }
#mt-settings-modal .mt-input-field { background: var(--b-field); border: 2px solid var(--b-soft); border-radius: 14px; color: var(--b-text); }
#mt-settings-modal .mt-input-field:focus { border-color: var(--b-accent); }
#mt-settings-modal .mt-btn-test, #mt-settings-modal .mt-btn-save { border: 2px solid var(--b-line); border-radius: 999px; background: var(--b-pill-off); box-shadow: var(--b-glow); color: var(--b-pill-off-ink); font-weight: 700; filter: none; }
#mt-settings-modal .mt-btn-save { background: var(--b-pill); color: #fff; }
#mt-settings-modal .mt-tag, #mt-settings-modal .mt-catalog-filter { border: 2px solid var(--b-soft); border-radius: 999px; background: var(--b-pill-off); color: var(--b-pill-off-ink); }
#mt-settings-modal .mt-tag.active, #mt-settings-modal .mt-catalog-filter.mt-is-active, #mt-settings-modal .mt-summary-tag { border-color: var(--b-line); background: var(--b-pill); color: #fff; }
#mt-settings-modal .mt-footer { background: transparent; border-top: 2px solid var(--b-soft); }
#mt-settings-modal .mt-subpanel, #mt-settings-modal .mt-catalog-card { background: var(--b-card2); border: 2px solid var(--b-soft); border-radius: 16px; }
#mt-settings-modal .mt-divider { border-top: 2px solid var(--b-soft); }
#mt-settings-modal code { background: var(--b-card2); border-radius: 6px; }
#mt-settings-modal .mt-content::-webkit-scrollbar, .mt-panel-list::-webkit-scrollbar { width: 6px; }
#mt-settings-modal .mt-content::-webkit-scrollbar-thumb, .mt-panel-list::-webkit-scrollbar-thumb { background: var(--b-accent2); border-radius: 6px; }

/* ===== ЖК-надписи: лаймовые, как на экранчиках ===== */
.mt-player-header, .mt-player-header-title, .mt-player-status, .mt-pl-modal-title, #mt-settings-modal .mt-header h3, #mt-settings-modal .mt-header-icon,
.mt-queue-item.mt-is-current .mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-now, .mt-pl-tab.mt-is-active, .mt-pl-tool.mt-pl-play, #mt-settings-modal .mt-btn-save {
    color: #c8f59a !important;
    text-shadow: 0 0 6px rgba(200, 245, 154, 0.45);
    letter-spacing: 0.05em;
}
.mt-player-header-title, #mt-settings-modal .mt-header h3 { text-transform: uppercase; }
.mt-track-title { font-family: 'Tektur', var(--b-font); text-transform: uppercase; letter-spacing: 0.04em; }
